SELECT fetched_date, investment_score, COALESCE(title_ja, title) AS title_ja_or_en, title, keywords, primary_category, url
FROM m_arxiv_papers
WHERE fetched_date >= (SELECT MAX(fetched_date) FROM m_arxiv_papers) - {{days}} AND investment_score >= {{min_score}}
ORDER BY investment_score DESC, fetched_date DESC
LIMIT {{limit}}

SELECT fetched_date, investment_score, COALESCE(title_ja, title) AS title_ja_or_en, keywords, primary_category, url
FROM m_arxiv_papers
WHERE title LIKE {{pattern}} OR summary LIKE {{pattern}} OR title_ja LIKE {{pattern}}
ORDER BY fetched_date DESC, investment_score DESC
LIMIT {{limit}}

SELECT keyword, COUNT(*) AS papers, SUM(CASE WHEN is_idea THEN 1 ELSE 0 END) AS ideas, ROUND(AVG(investment_score), 2) AS avg_score
FROM m_arxiv_keywords
WHERE fetched_date >= (SELECT MAX(fetched_date) FROM m_arxiv_keywords) - {{days}}
GROUP BY keyword
ORDER BY papers DESC
LIMIT {{limit}}

SELECT paper_id, fetched_date, published_date, investment_score, title, title_ja, authors, categories, keywords, summary, url
FROM m_arxiv_papers
WHERE paper_id = {{paper_id}}
